typedef struct BrakeHoldState {
    char pad00[0x4];
    float holdTime; /* 0x04 */
} BrakeHoldState;

unsigned char NokoNokoChallenge_HandleBrakeInput(BrakeHoldState *self, unsigned char brake) {
    if (!brake || g_ccClass == 2) {
        self->holdTime = 0.0f;
        return 0;
    }
    self->holdTime += 0.016666668f;
    if (self->holdTime >= 4.0f) {
        self->holdTime = 4.0f;
        return 1;
    }
    return 0;
}
